import{z as p,x as i,o as r,c as A,q as o,j as l,D as e,d as n,s as E,S as s}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"Alpa","description":"","frontmatter":{"title":"Alpa","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/alpa.md","filePath":"llm/alpa.md","lastUpdated":1791413859000}'),B={name:"llm/alpa.md"};function h(m,a,d,P,g,D){const t=i("Mermaid");return r(),A("div",null,[a[2]||(a[2]=o('<h1 id="alpa" tabindex="-1">Alpa <a class="header-anchor" href="#alpa" aria-label="Permalink to &quot;Alpa&quot;">​</a></h1><div class="epigraph"><p>把并行分成算子内切分与算子间流水线两层，分别用整数规划与动态规划搜，编译器就能在给定集群上吐出一份执行计划。</p><footer>—— Zheng 等，Alpa，arXiv:2201.12023，OSDI 2022</footer></div><p>UC Berkeley、Google、Amazon、上交等合作的 <strong>Alpa</strong>（Lianmin Zheng、Zhuohan Li、Hao Zhang、Yonghao Zhuang 等）把「手写 3D 网格」换成 <strong>编译自动并行</strong>。它不发明一种新的切法，而是统一数据并行、算子（张量）并行与流水线并行，在 JAX/XLA 上生成计划，运行时用 SPMD（<a href="/llm/gspmd">GSPMD</a>）执行算子内切分、用 MPMD 编排阶段。论文主张：在 Megatron 一类专门系统已经调过的 Transformer 上，自动计划能打平或超过手工；在异构模型、MoE、以及 GPU/TPU 拓扑不同时，手工网格更痛，编译器更有价值。代码在 <code>alpa-projects/alpa</code>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><span class="marginnote">术语翻译：自动并行就是让编译器替人回答「模型怎么切到一堆卡上」——哪些张量沿哪一维切开、哪些层串成流水线、每个副本喂多少数据。人只交出模型与集群描述，不再手写 Megatron 式网格。</span>训练计划要同时回答：多少数据并行副本、每个算子沿哪一轴切、图怎么切成流水线阶段、阶段怎么映射到哪些设备。搜索空间随层数与设备数指数膨胀。只搜流水线（阶段数、切点）会漏掉层内切分；只做算子并行（Mesh-TensorFlow / GSPMD 手工注解）会漏掉跨机该用点对点而不是每步 All-Reduce。手工系统还假设模型规整：全是一样的 Transformer 块。MoE 的专家轴、卷积与注意力混排，会让「全图一个 TP 度」失效。</p><p>集群本身是分层的：节点内高带宽、机架间低带宽。好的计划应当把 <strong>算子内</strong>（通信频繁）放进高带宽 mesh，把 <strong>算子间</strong>（阶段边界通信量小）放进跨 mesh 流水线。Alpa 的关键观察是：把并行重新分成这两层，就和集群的带宽层次对齐，搜索可以分层做，而不在一个扁平组合里穷举。</p><h3 id="算子内-vs-算子间" tabindex="-1">算子内 vs 算子间 <a class="header-anchor" href="#算子内-vs-算子间" aria-label="Permalink to &quot;算子内 vs 算子间&quot;">​</a></h3><p><strong>算子内（intra-op）</strong>：把单个张量算子沿 batch 或非 batch 轴切开，分到 mesh 上的设备，split/merge 时集体通信。这覆盖数据并行与 <a href="/llm/tensor-parallel">张量并行</a>。<strong>算子间（inter-op）</strong>：把图切成不相交阶段，阶段间流水线，通信只在边界。这覆盖 <a href="/llm/gpipe">GPipe</a> / <a href="/llm/pipedream">PipeDream</a> 一类。一份完整计划 = 如何分阶段、每阶段分到哪块 mesh、该阶段内每个算子怎么切。</p><p><span class="marginnote">用户 API 是 JAX 上的 <code>alpa.parallelize</code>（及可选的 pipeline 标记），不是在 PyTorch 里插 <code>f</code>/<code>g</code> 算子。Alpa 吃的是 JAX 计算图与集群描述。把 Alpa 理解成「Megatron 的 Python 封装」会找错代码路径。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>编译分三趟：</p><ol><li><strong>算子内 pass</strong>：在给定设备 mesh 上，用 <strong>整数线性规划（ILP）</strong> 为算子选切分轴，目标近似最小化该 mesh 上的延迟（计算 + 通信）。结果变成 GSPMD 注解。</li><li><strong>算子间 pass</strong>：用 <strong>动态规划</strong> 把算子聚类成阶段、把集群切成若干 mesh、做阶段–mesh 分配，目标是流水线吞吐（含气泡、负载均衡）。<span class="marginnote">术语翻译：ILP（整数线性规划）是在「每个算子只能从有限几个切法里选一个」的离散约束下，求总延迟最小的组合；动态规划则把「图切成几段、各分到哪个 mesh」拆成层层子问题记忆化，避免指数穷举。</span></li><li><strong>运行时编排</strong>：按阶段–mesh 对生成可执行文件；阶段内走 GSPMD 的 SPMD 运行时，阶段间走 Alpa 的流水线 runtime。</li></ol><p>因为层间 pass 依赖层内代价模型，实现上会先估或先跑层内再搜层间。异构模型上，不同阶段可以有不同的 intra-op 策略——这是手工「全局 TP=8」做不到的。论文评测包括 Transformer、异构结构与跨 GPU/TPU 设定，称自动计划匹配或超过专门手工系统。</p>',13)),(r(),l(s,null,{default:e(()=>[E(t,{id:"mermaid-51",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%5B%22JAX%20%E8%AE%AD%E7%BB%83%E6%AD%A5%20%2B%20%E9%9B%86%E7%BE%A4%E6%8B%93%E6%89%91%22%5D%20--%3E%20INTRA%5B%22Intra-op%EF%BC%9AILP%20%E9%80%89%E5%88%87%E5%88%86%E8%BD%B4%22%5D%0A%20%20INTRA%20--%3E%20SPMD%5B%22GSPMD%20%E6%B3%A8%E8%A7%A3%20%2F%20SPMD%20%E5%8F%AF%E6%89%A7%E8%A1%8C%22%5D%0A%20%20M%20--%3E%20INTER%5B%22Inter-op%EF%BC%9ADP%20%E5%88%87%E9%98%B6%E6%AE%B5%E4%B8%8E%20mesh%22%5D%0A%20%20INTER%20--%3E%20PIPE%5B%22%E9%98%B6%E6%AE%B5%E9%97%B4%E6%B5%81%E6%B0%B4%E7%BA%BF%22%5D%0A%20%20SPMD%20--%3E%20RT%5B%22Runtime%20%E7%BC%96%E6%8E%92%22%5D%0A%20%20PIPE%20--%3E%20RT%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o('<h3 id="代价模型与「编译多久」" tabindex="-1">代价模型与「编译多久」 <a class="header-anchor" href="#代价模型与「编译多久」" aria-label="Permalink to &quot;代价模型与「编译多久」&quot;">​</a></h3><p>ILP 不能对真实逐步模拟每一个 kernel，只能用分析式的计算/通信估计。估计偏差会选出局部最优：例如低估 All-Reduce 延迟就会切得过碎。动态规划的阶段数与切点若限制在「沿层堆的切缝」，搜索可解；若允许任意算子重排，空间再次爆炸。因此 Alpa 仍假设训练步主要是层叠的前向–反向图，不是任意动态控制流。编译本身有开销，适合步数极多的预训练，不适合每次改两行超参就重编译的交互式调试——那是相对 Megatron 手写网格的另一笔账。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>分层优化能收敛到好计划，是因为两层的通信形貌几乎不重叠：intra-op 的集体通信延迟对 NVLink/TPU mesh 敏感，inter-op 的激活体积是 \\(b\\times s\\times d\\) 一次边界传输。先固定 mesh 内的切分，再决定哪些层共用一个 mesh，相当于先解决高带宽子问题，再解决低带宽管道。这与人手写「TP 节点内、PP 跨节点」同构，但切点、每阶段 TP 度、是否对某层沿 batch 而非隐藏维切，都可以变。<span class="marginnote">直觉类比：算子内切分像车间内部分工——一道工序怎么拆给本车间的工人，拆得越细工人间喊话（通信）越频繁，所以必须放在高带宽的同一间厂房；算子间流水线像车间之间的传送带，只在交接处递一次半成品。</span></p>',4)),(r(),l(s,null,{default:e(()=>[E(t,{id:"mermaid-64",class:"mermaid",graph:"flowchart%20TD%0A%20%20G%5B%22%E8%AE%AD%E7%BB%83%E5%9B%BE%20%2B%20%E9%9B%86%E7%BE%A4%E6%8B%93%E6%89%91%22%5D%20--%3E%20CUT%5B%22%E5%8A%A8%E6%80%81%E8%A7%84%E5%88%92%EF%BC%9A%E5%88%87%E9%98%B6%E6%AE%B5%E3%80%81%E9%85%8D%20mesh%3Cbr%2F%3E%EF%BC%88%E7%AE%97%E5%AD%90%E9%97%B4%EF%BC%9A%E8%BE%B9%E7%95%8C%E9%80%9A%E4%BF%A1%E5%B0%8F%EF%BC%89%22%5D%0A%20%20CUT%20--%3E%20S1%5B%22%E9%98%B6%E6%AE%B5%201%20%E2%86%92%20%E8%8A%82%E7%82%B9%E5%86%85%20mesh%22%5D%0A%20%20CUT%20--%3E%20S2%5B%22%E9%98%B6%E6%AE%B5%202%20%E2%86%92%20%E5%8F%A6%E4%B8%80%E8%8A%82%E7%82%B9%E5%86%85%20mesh%22%5D%0A%20%20S1%20--%3E%20ILP%5B%22ILP%EF%BC%9A%E4%B8%BA%E6%AF%8F%E4%B8%AA%E7%AE%97%E5%AD%90%E9%80%89%E5%88%87%E5%88%86%E8%BD%B4%3Cbr%2F%3E%EF%BC%88%E7%AE%97%E5%AD%90%E5%86%85%EF%BC%9A%E9%80%9A%E4%BF%A1%E9%A2%91%E7%B9%81%EF%BC%8C%E8%B5%B0%E9%AB%98%E5%B8%A6%E5%AE%BD%EF%BC%89%22%5D%0A%20%20S2%20--%3E%20ILP%0A%20%20ILP%20--%3E%20P%5B%22%E6%B5%81%E6%B0%B4%E7%BA%BF%E6%89%A7%E8%A1%8C%EF%BC%9A%E9%98%B6%E6%AE%B5%E9%97%B4%E5%8F%AA%E4%BC%A0%E4%B8%80%E6%AC%A1%E6%BF%80%E6%B4%BB%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=o('<p>MoE 上，专家轴是合法的 intra-op 轴；不同拓扑上最优轴不同（论文用 MoE Transformer 在 TPU vs GPU 上需要不同切分与不同流水线来说明自动化动机）。Alpa 并不保证搜到全局最优，ILP 有超时与启发式；它保证的是搜索空间覆盖三种经典并行，而不是覆盖全部并行研究（例如当时未把专家并行写成独立于张量的第五维产品名）。</p><p><span class="marginnote">OSDI 2022 的对照系统是当时的 Megatron 等手工栈。2024 年后 PyTorch FSDP、Megatron Core、torch.distributed 的设备 mesh 缩小了「必须用 JAX 才能自动切」的差距。Alpa 的贡献仍是分层空间 + ILP/DP，不是永久的吞吐冠军。</span></p><h3 id="和-megatron-deepspeed、gspmd-单独用" tabindex="-1">和 Megatron-DeepSpeed、GSPMD 单独用 <a class="header-anchor" href="#和-megatron-deepspeed、gspmd-单独用" aria-label="Permalink to &quot;和 Megatron-DeepSpeed、GSPMD 单独用&quot;">​</a></h3><p><a href="/llm/megatron-deepspeed">Megatron-DeepSpeed</a> 给的是一份已验证的 8×35×DP 配方。Alpa 给的是「换模型、换集群时重新搜」。只用 GSPMD 仍要人标轴；Alpa 在 XLA 里自动标。训练生产若模型极规整、集群极固定，手工网格可能更易调试；若每周改结构，编译器更值。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>JAX 生态与 PyTorch 预训练主流分叉：迁移成本是真实的。动态 shape、数据相关控制流、自定义算子会让 ILP 图不完整。流水线仍有气泡与权重版本问题，Alpa 没有取消 <a href="/llm/pipedream">PipeDream</a> 里那些物理约束，只是自动选阶段。代价模型过时（新的 FlashAttention、新的 NVLink 带宽）需要重新标定，否则计划停留在旧硬件画像上。</p><p>不要把 Alpa 写成「零标注永远最优」。pipeline mark 仍可能需要。论文编号 2201.12023 与 MT-NLG 的 2201.11990 相邻，不要抄串。</p><p><span class="marginnote">真实编号：Zheng、Li、Zhang 等 <em>Alpa: Automating Inter- and Intra-Operator Parallelism for Distributed Deep Learning</em>，arXiv:2201.12023，OSDI 2022。GSPMD 是 Xu 等的工作，另文。禁止给 Alpa 再编一个「PyTorch 官方移植」假论文号。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Alpa 用 intra-op（ILP）与 inter-op（动态规划）分层自动生成数据/张量/流水线计划。</li><li>实现于 JAX/XLA，阶段内 SPMD、阶段间流水线运行时。</li><li>目标是换模型与换集群时少手写网格，而非取代所有手工 3D 配方。</li><li>出处：Zheng 等，arXiv:2201.12023，2022。</li></ul>',10))])}const u=p(B,[["render",h]]);export{T as __pageData,u as default};
